function dedupeDriveMedia(records) {
	const seen = /* @__PURE__ */ new Set();
	return records.flatMap((record) => {
		const aiLabelled = /chatgpt|gemini/i.test(record.sourceName);
		const key = record.contentHash ? `hash:${record.contentHash}` : `drive:${record.driveFileId}`;
		if (seen.has(key)) return [];
		seen.add(key);
		return [{
			...record,
			authenticity: aiLabelled ? "ai-concept" : record.authenticity,
			publishStatus: aiLabelled ? "quarantined" : record.publishStatus,
			orientation: record.orientation ?? "unknown",
			quality: record.quality ?? "editorial",
			derived: record.derived ?? { webp: record.localSrc }
		}];
	});
}
